import GallerySectionV5 from "./components/gallery-section-v5"

export default function Page() {
  return <GallerySectionV5 />
}

import { GalleryArcCard } from "./gallery-arc-card"
import { createBlockImage } from "@/lib/block-media"
import {
  RING_SLOTS,
  galleryFiles,
  sectionMeta,
  type GalleryItem,
} from "../lib/config"
import "../styles/gallery-section-v5.css"

const blockImage = createBlockImage("gallery-section-v5")
const galleryItems: GalleryItem[] = galleryFiles.map(({ file, alt }, index) => ({
  id: String(index + 1),
  alt,
  imageSrc: blockImage(file),
}))

export type GallerySectionV5Props = {
  header?: { title: string; description?: string } | false
  items?: GalleryItem[]
}

export default function GallerySectionV5({
  header = sectionMeta,
  items = galleryItems,
}: GallerySectionV5Props = {}) {
  const slots = Array.from({ length: RING_SLOTS }, (_, slot) => ({
    slot,
    item: items[slot % items.length],
  }))

  return (
    <section className="gsv5-stage relative isolate overflow-hidden py-4 md:py-6 lg:py-8">
      <div aria-hidden className="gsv5-fade pointer-events-none absolute inset-0 -z-10">
        <div className="gsv5-orbit absolute left-1/2 rounded-full border border-dashed border-border" />
      </div>

      <div className="gsv5-fade absolute inset-0 -z-10">
        <ul className="gsv5-ring absolute left-1/2" aria-label="Gallery">
          {slots.map(({ slot, item }) => (
            <GalleryArcCard
              key={slot}
              item={item}
              angle={(360 / RING_SLOTS) * slot}
              decorative={slot >= items.length}
              priority={slot < 3 || slot > RING_SLOTS - 3}
            />
          ))}
        </ul>
      </div>

      {header !== false ? (
        <div className="gsv5-header pointer-events-none mx-auto max-w-md px-4 text-center *:pointer-events-auto">
          <h2 className="text-4xl font-medium leading-[1.1] tracking-[-0.03em] lg:text-5xl">
            {header.title}
          </h2>
          {header.description ? (
            <p className="mx-auto mt-4 max-w-sm text-[0.9375rem] leading-relaxed text-muted-foreground">
              {header.description}
            </p>
          ) : null}
        </div>
      ) : null}
    </section>
  )
}

import type { CSSProperties } from "react"
import Image from "next/image"

import type { GalleryItem } from "../lib/config"

type GalleryArcCardProps = {
  item: GalleryItem
  angle: number
  /** Repeated copies are decorative — only the first pass is announced. */
  decorative?: boolean
  priority?: boolean
}

export function GalleryArcCard({
  item,
  angle,
  decorative = false,
  priority = false,
}: GalleryArcCardProps) {
  return (
    <li
      className="gsv5-card"
      style={{ "--gsv5-angle": `${angle}deg` } as CSSProperties}
      aria-hidden={decorative || undefined}
    >
      <div className="relative size-full overflow-hidden rounded-2xl bg-muted shadow-xl shadow-foreground/10 ring-1 ring-border transition-transform duration-500 ease-out hover:scale-105">
        <Image
          src={item.imageSrc}
          alt={decorative ? "" : item.alt}
          fill
          unoptimized
          priority={priority}
          sizes="13rem"
          className="object-cover"
        />
      </div>
    </li>
  )
}

export type GalleryItem = {
  id: string
  imageSrc: string
  alt: string
}

export const sectionMeta = {
  title: "Always something new on the easel",
  description:
    "Recent canvases and paper studies drift past one by one.",
} as const

/** Cards spaced evenly around the full ring — items repeat to fill every slot. */
export const RING_SLOTS = 20

export const galleryFiles = [
  { file: "image-1.jpg", alt: "Oil painting of a morning harbor" },
  { file: "image-2.jpg", alt: "Acrylic field study painting" },
  { file: "image-3.jpg", alt: "Oil painting of a quiet interior" },
  { file: "image-4.jpg", alt: "Watercolor of coastal light" },
  { file: "image-5.jpg", alt: "Oil painting of an autumn orchard" },
] as const

/* Ring geometry — the ring is a 0×0 point at the circle's center; each card
   is rotated to its slot then pushed out by the radius, so rotating the point
   spins the whole arc. One full turn loops seamlessly. */
.gsv5-stage {
  --gsv5-card: 7rem;
  --gsv5-radius: 28rem;
  --gsv5-top: 2.5rem;
  --gsv5-center: calc(var(--gsv5-top) + var(--gsv5-card) / 2 + var(--gsv5-radius));
  min-height: calc(var(--gsv5-top) + var(--gsv5-card) / 2 + var(--gsv5-radius) * 0.7);
}

@media (min-width: 768px) {
  .gsv5-stage {
    --gsv5-card: 11rem;
    --gsv5-radius: 40rem;
    --gsv5-top: 3rem;
  }
}

@media (min-width: 1024px) {
  .gsv5-stage {
    --gsv5-card: 13rem;
    --gsv5-radius: 48rem;
  }
}

.gsv5-fade {
  mask-image: linear-gradient(to bottom, #000 50%, transparent 92%);
}

.gsv5-orbit {
  top: calc(var(--gsv5-center) - var(--gsv5-radius));
  width: calc(var(--gsv5-radius) * 2);
  height: calc(var(--gsv5-radius) * 2);
  translate: -50% 0;
}

.gsv5-ring {
  top: var(--gsv5-center);
  width: 0;
  height: 0;
  animation: gsv5-spin 90s linear infinite;
}

.gsv5-ring:has(.gsv5-card:hover) {
  animation-play-state: paused;
}

.gsv5-card {
  position: absolute;
  top: calc(var(--gsv5-card) / -2);
  left: calc(var(--gsv5-card) / -2);
  width: var(--gsv5-card);
  height: var(--gsv5-card);
  transform: rotate(var(--gsv5-angle)) translateY(calc(var(--gsv5-radius) * -1));
}

.gsv5-header {
  padding-top: calc(var(--gsv5-top) + var(--gsv5-card) + 2.5rem);
  padding-bottom: 4rem;
}

@keyframes gsv5-spin {
  to {
    transform: rotate(360deg);
  }
}

@media (prefers-reduced-motion: reduce) {
  .gsv5-ring {
    animation-play-state: paused;
  }
}
